          "archivo": "Form1.frm",
          "codigo": "Option Explicit\n\nDim X As String\n\nPrivate Sub CargarImagen()\n    On Error Resume Next\n    Dim ruta As String\n    ruta = App.Path & \"\\\" & Trim(Label5.Caption)\n    If Trim(Label5.Caption) <> \"\" And Dir(ruta) <> \"\" Then\n        Image1.Picture = LoadPicture(ruta)\n    Else\n        Set Image1.Picture = Nothing\n    End If\nEnd Sub\n\nPrivate Sub Avanzar_Click(Index As Integer)\n    On Error Resume Next\n    Adodc1.Recordset.MoveNext\n    If Adodc1.Recordset.EOF Then\n        Adodc1.Recordset.MovePrevious\n    End If\n    CargarImagen\nEnd Sub\n\nPrivate Sub Regrezar_Click(Index As Integer)\n    On Error Resume Next\n    Adodc1.Recordset.MovePrevious\n    If Adodc1.Recordset.BOF Then\n        Adodc1.Recordset.MoveNext\n    End If\n    CargarImagen\nEnd Sub\n\nPrivate Sub Command1_Click()\n    On Error Resume Next\n    Adodc1.Recordset.MoveFirst\n    CargarImagen\nEnd Sub\n\nPrivate Sub Command2_Click()\n    On Error Resume Next\n    Adodc1.Recordset.MoveLast\n    CargarImagen\nEnd Sub\n\nPrivate Sub Command3_Click()\n    On Error Resume Next\n    If LCase(Trim(Command3.Caption)) = \"nuevo\" Then\n        Adodc1.Recordset.AddNew\n        Text5.Visible = True\n        Command3.Caption = \"Guardar\"\n    Else\n        Command3.Caption = \"Nuevo\"\n        Adodc1.Recordset.Update\n        Adodc1.Recordset.MoveLast\n        Text5.Visible = False\n        MsgBox \"Se guardo correctamente el nuevo registro\", vbInformation, \"Registro Guardado\"\n    End If\nEnd Sub\n\nPrivate Sub Command4_Click()\n    On Error Resume Next\n    Adodc1.Recordset.Update\n    Adodc1.Recordset.MoveLast\n    Text5.Visible = False\n    MsgBox \"Se guardo correctamente el registro\", vbInformation, \"Registro Actualizado\"\nEnd Sub\n\nPrivate Sub Command5_Click()\n    On Error Resume Next\n    Abrir.Filter = \"Archivos de imagen (*.jpg;*.bmp;*.gif)|*.jpg;*.bmp;*.gif|Todos los archivos (*.*)|*.*\"\n    Abrir.DialogTitle = \"Seleccionar Imagen\"\n    Abrir.InitDir = App.Path\n    Abrir.ShowOpen\n    If Abrir.FileName <> \"\" Then\n        Image1.Picture = LoadPicture(Abrir.FileName)\n        Text5.Text = Abrir.FileTitle\n        Label5.Caption = Abrir.FileTitle\n    End If\nEnd Sub\n\nPrivate Sub Command6_Click()\n    On Error Resume Next\n    Adodc1.Recordset.Update\n    MsgBox \"Registro modificado con exito\", vbInformation, \"Actualizado\"\nEnd Sub\n\nPrivate Sub Form_Load()\n    On Error Resume Next\n    X = App.Path\n    Adodc1.ConnectionString = \"Provider=Microsoft.Jet.OLEDB.4.0;Data Source=\" & App.Path & \"\\personas.mdb;Persist Security Info=False\"\n    Adodc1.RecordSource = \"uno\"\n    Adodc1.Refresh\n    CargarImagen\n    With Abrir\n        .Filter = \"Archivos de imagen (*.jpg;*.bmp;*.gif)|*.jpg;*.bmp;*.gif|Todos los archivos (*.*)|*.*\"\n        .DialogTitle = \"Seleccionar Imagen\"\n        .InitDir = App.Path\n    End With\nEnd Sub"
