          "archivo": "Form1.frm",
          "codigo": "Option Explicit\n\nPrivate Function ObtenerNumeros(ByRef N1 As Double, ByRef N2 As Double) As Boolean\n    If Trim(txtNum1.Text) = \"\" Or Not IsNumeric(txtNum1.Text) Then\n        MsgBox \"Por favor, introduce un primer número válido.\", vbExclamation, \"Dato inválido\"\n        txtNum1.SetFocus\n        ObtenerNumeros = False\n        Exit Function\n    End If\n    If Trim(txtNum2.Text) = \"\" Or Not IsNumeric(txtNum2.Text) Then\n        MsgBox \"Por favor, introduce un segundo número válido.\", vbExclamation, \"Dato inválido\"\n        txtNum2.SetFocus\n        ObtenerNumeros = False\n        Exit Function\n    End If\n    N1 = CDbl(txtNum1.Text)\n    N2 = CDbl(txtNum2.Text)\n    ObtenerNumeros = True\nEnd Function\n\nPrivate Sub cmdSumar_Click()\n    Dim a As Double, b As Double\n    If ObtenerNumeros(a, b) Then\n        lblResultado.Caption = Format(a + b, \"#,##0.######\")\n    End If\nEnd Sub\n\nPrivate Sub cmdRestar_Click()\n    Dim a As Double, b As Double\n    If ObtenerNumeros(a, b) Then\n        lblResultado.Caption = Format(a - b, \"#,##0.######\")\n    End If\nEnd Sub\n\nPrivate Sub cmdMultiplicar_Click()\n    Dim a As Double, b As Double\n    If ObtenerNumeros(a, b) Then\n        lblResultado.Caption = Format(a * b, \"#,##0.######\")\n    End If\nEnd Sub\n\nPrivate Sub cmdDividir_Click()\n    Dim a As Double, b As Double\n    If ObtenerNumeros(a, b) Then\n        If b = 0 Then\n            MsgBox \"Error matemático: No es posible dividir entre cero.\", vbCritical, \"División entre Cero\"\n            lblResultado.Caption = \"Error (div / 0)\"\n        Else\n            lblResultado.Caption = Format(a / b, \"#,##0.######\")\n        End If\n    End If\nEnd Sub\n\nPrivate Sub cmdLimpiar_Click()\n    txtNum1.Text = \"\"\n    txtNum2.Text = \"\"\n    lblResultado.Caption = \"0\"\n    txtNum1.SetFocus\nEnd Sub\n\nPrivate Sub cmdSalir_Click()\n    Unload Me\n    End\nEnd Sub"
