        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\n\nPrivate Sub Form_Load()\n    cboCategoria.AddItem \"1. Temperatura\"\n    cboCategoria.AddItem \"2. Longitud / Distancia\"\n    cboCategoria.AddItem \"3. Masa / Peso\"\n    cboCategoria.AddItem \"4. Almacenamiento Digital\"\n    cboCategoria.ListIndex = 0\nEnd Sub\n\nPrivate Sub cboCategoria_Click()\n    cboDe.Clear\n    cboA.Clear\n\n    Select Case cboCategoria.ListIndex\n        Case 0\n            cboDe.AddItem \"Celsius (°C)\"\n            cboDe.AddItem \"Fahrenheit (°F)\"\n            cboDe.AddItem \"Kelvin (K)\"\n\n            cboA.AddItem \"Celsius (°C)\"\n            cboA.AddItem \"Fahrenheit (°F)\"\n            cboA.AddItem \"Kelvin (K)\"\n\n            cboDe.ListIndex = 0\n            cboA.ListIndex = 1\n\n        Case 1\n            cboDe.AddItem \"Metros (m)\"\n            cboDe.AddItem \"Kilómetros (km)\"\n            cboDe.AddItem \"Centímetros (cm)\"\n            cboDe.AddItem \"Milímetros (mm)\"\n            cboDe.AddItem \"Millas (mi)\"\n            cboDe.AddItem \"Pies (ft)\"\n            cboDe.AddItem \"Pulgadas (in)\"\n\n            cboA.AddItem \"Metros (m)\"\n            cboA.AddItem \"Kilómetros (km)\"\n            cboA.AddItem \"Centímetros (cm)\"\n            cboA.AddItem \"Milímetros (mm)\"\n            cboA.AddItem \"Millas (mi)\"\n            cboA.AddItem \"Pies (ft)\"\n            cboA.AddItem \"Pulgadas (in)\"\n\n            cboDe.ListIndex = 1\n            cboA.ListIndex = 0\n\n        Case 2\n            cboDe.AddItem \"Kilogramos (kg)\"\n            cboDe.AddItem \"Gramos (g)\"\n            cboDe.AddItem \"Libras (lb)\"\n            cboDe.AddItem \"Onzas (oz)\"\n            cboDe.AddItem \"Toneladas (t)\"\n\n            cboA.AddItem \"Kilogramos (kg)\"\n            cboA.AddItem \"Gramos (g)\"\n            cboA.AddItem \"Libras (lb)\"\n            cboA.AddItem \"Onzas (oz)\"\n            cboA.AddItem \"Toneladas (t)\"\n\n            cboDe.ListIndex = 0\n            cboA.ListIndex = 2\n\n        Case 3\n            cboDe.AddItem \"Bytes (B)\"\n            cboDe.AddItem \"Kilobytes (KB)\"\n            cboDe.AddItem \"Megabytes (MB)\"\n            cboDe.AddItem \"Gigabytes (GB)\"\n            cboDe.AddItem \"Terabytes (TB)\"\n\n            cboA.AddItem \"Bytes (B)\"\n            cboA.AddItem \"Kilobytes (KB)\"\n            cboA.AddItem \"Megabytes (MB)\"\n            cboA.AddItem \"Gigabytes (GB)\"\n            cboA.AddItem \"Terabytes (TB)\"\n\n            cboDe.ListIndex = 3\n            cboA.ListIndex = 2\n    End Select\n\n    Convertir\nEnd Sub\n\nPrivate Sub cmdConvertir_Click()\n    Convertir\nEnd Sub\n\nPrivate Sub txtValor_Change()\n    Convertir\nEnd Sub\n\nPrivate Sub cboDe_Click()\n    Convertir\nEnd Sub\n\nPrivate Sub cboA_Click()\n    Convertir\nEnd Sub\n\nPrivate Sub cmdSwap_Click()\n    Dim idxDe As Integer, idxA As Integer\n    idxDe = cboDe.ListIndex\n    idxA = cboA.ListIndex\n    cboDe.ListIndex = idxA\n    cboA.ListIndex = idxDe\nEnd Sub\n\nPrivate Sub cmdLimpiar_Click()\n    txtValor.Text = \"0\"\n    Convertir\nEnd Sub\n\nPrivate Sub cmdSalir_Click()\n    Unload Me\n    End\nEnd Sub\n\nPrivate Sub Convertir()\n    If Trim(txtValor.Text) = \"\" Or Not IsNumeric(txtValor.Text) Then\n        lblResultado.Caption = \"0\"\n        lblFormula.Caption = \"Ingresa un valor numérico\"\n        Exit Sub\n    End If\n\n    Dim V As Double, R As Double\n    Dim Formula As String\n    V = CDbl(txtValor.Text)\n\n    Select Case cboCategoria.ListIndex\n        Case 0\n            R = ConvertirTemperatura(V, cboDe.ListIndex, cboA.ListIndex, Formula)\n        Case 1\n            R = ConvertirLongitud(V, cboDe.ListIndex, cboA.ListIndex, Formula)\n        Case 2\n            R = ConvertirMasa(V, cboDe.ListIndex, cboA.ListIndex, Formula)\n        Case 3\n            R = ConvertirDigital(V, cboDe.ListIndex, cboA.ListIndex, Formula)\n    End Select\n\n    lblResultado.Caption = Format(R, \"#,##0.######\") & \" \" & cboA.Text\n    lblFormula.Caption = Formula\nEnd Sub\n\nPrivate Function ConvertirTemperatura(V As Double, De As Integer, A As Integer, ByRef F As String) As Double\n    Dim celsius As Double\n\n    Select Case De\n        Case 0: celsius = V\n        Case 1: celsius = (V - 32) * 5 / 9\n        Case 2: celsius = V - 273.15\n    End Select\n\n\n    Dim res As Double\n    Select Case A\n        Case 0\n            res = celsius\n            F = V & \" ° = \" & Format(res, \"0.##\") & \" °C\"\n        Case 1\n            res = (celsius * 9 / 5) + 32\n            F = \"Fórmula: (°C × 9/5) + 32 = \" & Format(res, \"0.##\") & \" °F\"\n        Case 2\n            res = celsius + 273.15\n            F = \"Fórmula: °C + 273.15 = \" & Format(res, \"0.##\") & \" K\"\n    End Select\n    ConvertirTemperatura = res\nEnd Function\n\nPrivate Function ConvertirLongitud(V As Double, De As Integer, A As Integer, ByRef F As String) As Double\n\n    Dim aMetros(6) As Double\n    aMetros(0) = 1#\n    aMetros(1) = 1000#\n    aMetros(2) = 0.01\n    aMetros(3) = 0.001\n    aMetros(4) = 1609.344\n    aMetros(5) = 0.3048\n    aMetros(6) = 0.0254\n\n    Dim metros As Double\n    metros = V * aMetros(De)\n    Dim res As Double\n    res = metros / aMetros(A)\n    F = V & \" en metros = \" & Format(metros, \"0.######\") & \" m\"\n    ConvertirLongitud = res\nEnd Function\n\nPrivate Function ConvertirMasa(V As Double, De As Integer, A As Integer, ByRef F As String) As Double\n\n    Dim aKg(4) As Double\n    aKg(0) = 1#\n    aKg(1) = 0.001\n    aKg(2) = 0.45359237\n    aKg(3) = 0.02834952\n    aKg(4) = 1000#\n\n    Dim kg As Double\n    kg = V * aKg(De)\n    Dim res As Double\n    res = kg / aKg(A)\n    F = V & \" en kilogramos = \" & Format(kg, \"0.######\") & \" kg\"\n    ConvertirMasa = res\nEnd Function\n\nPrivate Function ConvertirDigital(V As Double, De As Integer, A As Integer, ByRef F As String) As Double\n\n    Dim pot As Integer\n    pot = De - A\n    Dim res As Double\n    res = V * (1024# ^ pot)\n    F = \"Relación base 1024: 1 unidad = 1024 de la anterior\"\n    ConvertirDigital = res\nEnd Function"
        }
