          "archivo": "Form1.frm",
          "codigo": "Private Sub cmdagregar_Click()\n    Dim nuevafruta As String\n    nuevafruta = InputBox(\"Cual es su nueva fruta\", \"Rica Fruta\")\n    If nuevafruta <> \"\" Then\n        lstfrutas.AddItem nuevafruta\n        lblcuantos.Caption = lstfrutas.ListCount\n    Else\n        MsgBox \"No hay elementos nuevos\", , \"Uso de listbox\"\n    End If\nEnd Sub\n\nPrivate Sub cmdeliminar_Click()\n    Dim intresp As Integer\n    intresp = MsgBox(\"Deseas eliminar el registro\", vbYesNo + vbQuestion + vbDefaultButton2, \"Manejo de frutas\")\n    If intresp = vbYes Then\n        lstfrutas.RemoveItem (lstfrutas.ListIndex)\n        lblcuantos.Caption = lstfrutas.ListCount\n        txtfrutas.Text = \"\"\n    Else\n        MsgBox \"Cancela la opcion de Eliminar\", vbOKOnly + vbInformation, \"Manejo de Frutas\"\n    End If\nEnd Sub\n\nPrivate Sub cmdlimpiar_Click()\n    lstfrutas.Clear\n    txtfrutas = \"\"\nEnd Sub\n\nPrivate Sub cmdsalir_Click()\n    End\nEnd Sub\n\nPrivate Sub Form_Load()\n    lstfrutas.AddItem \"Manzana\"\n    lstfrutas.AddItem \"Pera\"\nEnd Sub\n\nPrivate Sub lstfrutas_Click()\n\nEnd Sub"
