          "archivo": "Form1.frm",
          "codigo": "Private Sub Command1_Click()\nDim art As String\nDim precio As String\nDim exi As String\nart = InputBox(\"Agregue su nuevo producto\", \"Nuevo Producto\")\nIf art <> \"\" Then\nlista.AddItem art\ntotal.Caption = lista.ListCount\nElse\nMsgBox \"No ingresaste ningun producto\", , \"PRECAUCION\"\nGoTo fin\nEnd If\nregresa:\nprecio = InputBox(\"Ingresa su precio\", \"Nuevo producto\")\nIf precio <> \"\" Then\ncost.AddItem precio\nElse\nMsgBox \"No ingreso su precio\", , \"PRECAUCION\"\nGoTo regresa\nEnd If\nregresa2:\nexi = InputBox(\"Ingresa sus existencias\", \"Nuevo producto\")\nIf exi <> \"\" Then\nexis.AddItem exi\nElse\nMsgBox \"No ingreso existencias\", , \"PRECAUCION\"\nGoTo regresa2\nEnd If\nfin:\nEnd Sub\nPrivate Sub Command2_Click()\nDim intresp As Integer\nIf lista.ListIndex = -1 Then\nMsgBox \"Seleccione un registro de la lista para eliminar\", vbExclamation, \"Atencion\"\nExit Sub\nEnd If\nintresp = MsgBox(\"Desea eliminar el registro seleccionado de la lista?\", vbYesNo + vbQuestion + vbDefaultButton2, \"Eliminar\")\nIf intresp = vbYes Then\ncost.RemoveItem (lista.ListIndex)\nexis.RemoveItem (lista.ListIndex)\nlista.RemoveItem (lista.ListIndex)\ntotal.Caption = lista.ListCount\nElse\nMsgBox \"Se cancelo la opcion de eliminar\", vbOKOnly + vbInformation, \"Cancelar\"\nEnd If\nEnd Sub\nPrivate Sub Command3_Click()\nDim intresp As Integer\nintresp = MsgBox(\"Desea guardar el registro?\", vbYesNo + vbQuestion + vbDefaultButton2, \"Guardar Archivo\")\nIf intresp = vbYes Then\nOn Error Resume Next\nKill (App.Path & \"\\Papeleria.txt\")\nKill (App.Path & \"\\PapeleriaS.txt\")\nKill (App.Path & \"\\PapeleriaE.txt\")\nOn Error GoTo 0\nDim I As Integer\nDim J As Integer\nDim X As Integer\nOpen App.Path & \"\\Papeleria.txt\" For Append As #1\nFor I = 0 To lista.ListCount - 1\nPrint #1, lista.List(I)\nNext I\nClose #1\nOpen App.Path & \"\\PapeleriaS.txt\" For Append As #2\nFor J = 0 To cost.ListCount - 1\nPrint #2, cost.List(J)\nNext J\nClose #2\nOpen App.Path & \"\\PapeleriaE.txt\" For Append As #3\nFor X = 0 To exis.ListCount - 1\nPrint #3, exis.List(X)\nNext X\nClose #3\nMsgBox \"Registros guardados con exito en los archivos de texto.\", vbInformation, \"Guardado exitoso\"\nEnd If\nEnd Sub\nPrivate Sub Command4_Click()\nEnd\nEnd Sub\nPrivate Sub Command5_Click()\nDim I As Integer\nDim encontrado As Boolean\nencontrado = False\nIf Trim$(Text1.Text) = \"\" Then\nMsgBox \"Ingrese el nombre del articulo a buscar\", vbExclamation, \"Buscar\"\nExit Sub\nEnd If\nFor I = 0 To lista.ListCount - 1\nIf LCase$(lista.List(I)) = LCase$(Trim$(Text1.Text)) Then\nlblArticulo.Caption = lista.List(I)\nlblPrecio.Caption = cost.List(I)\nlblExistencias.Caption = exis.List(I)\nlista.ListIndex = I\ncost.ListIndex = I\nexis.ListIndex = I\nencontrado = True\nExit For\nEnd If\nNext I\nIf Not encontrado Then\nMsgBox \"No se encontro el articulo en el inventario\", vbInformation, \"Resultado de busqueda\"\nlblArticulo.Caption = \"\"\nlblPrecio.Caption = \"\"\nlblExistencias.Caption = \"\"\nEnd If\nEnd Sub\nPrivate Sub lista_Click()\nIf lista.ListIndex >= 0 Then\ncost.ListIndex = lista.ListIndex\nexis.ListIndex = lista.ListIndex\nlblArticulo.Caption = lista.List(lista.ListIndex)\nlblPrecio.Caption = cost.List(lista.ListIndex)\nlblExistencias.Caption = exis.List(lista.ListIndex)\nEnd If\nEnd Sub\nPrivate Sub cost_Click()\nIf cost.ListIndex >= 0 Then\nlista.ListIndex = cost.ListIndex\nexis.ListIndex = cost.ListIndex\nEnd If\nEnd Sub\nPrivate Sub exis_Click()\nIf exis.ListIndex >= 0 Then\nlista.ListIndex = exis.ListIndex\ncost.ListIndex = exis.ListIndex\nEnd If\nEnd Sub\nPrivate Sub Form_Load()\nDim linea As String\nIf Dir$(App.Path & \"\\Papeleria.txt\") <> \"\" Then\nOpen App.Path & \"\\Papeleria.txt\" For Input As #1\nDo While Not EOF(1)\nLine Input #1, linea\nIf Trim$(linea) <> \"\" Then lista.AddItem Trim$(linea)\nLoop\nClose #1\nEnd If\nIf Dir$(App.Path & \"\\PapeleriaS.txt\") <> \"\" Then\nOpen App.Path & \"\\PapeleriaS.txt\" For Input As #2\nDo While Not EOF(2)\nLine Input #2, linea\nIf Trim$(linea) <> \"\" Then cost.AddItem Trim$(linea)\nLoop\nClose #2\nEnd If\nIf Dir$(App.Path & \"\\PapeleriaE.txt\") <> \"\" Then\nOpen App.Path & \"\\PapeleriaE.txt\" For Input As #3\nDo While Not EOF(3)\nLine Input #3, linea\nIf Trim$(linea) <> \"\" Then exis.AddItem Trim$(linea)\nLoop\nClose #3\nEnd If\ntotal.Caption = lista.ListCount\nEnd Sub"
