        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\n\nDim conn As Connection\nDim rs As Recordset\n\nPrivate Sub Form_Load()\n    On Error Resume Next\n    Set conn = New Connection\n    Set rs = New Recordset\n    conn.Open \"Provider=Microsoft.Jet.OLEDB.4.0;Data Source=\" & App.Path & \"\\nomina.mdb;Persist Security Info=False\"\n    rs.Open \"SELECT * FROM Nomina ORDER BY Id\", conn, adOpenDynamic, adLockOptimistic\n\n    If Not (rs.BOF And rs.EOF) Then\n        CargarRegistroActual\n    Else\n        LimpiarCampos\n    End If\nEnd Sub\n\nPrivate Sub CargarRegistroActual()\n    On Error Resume Next\n    If Not (rs.BOF Or rs.EOF) Then\n        txtApPaterno.Text = rs.Fields(\"ApPaterno\") & \"\"\n        txtApMaterno.Text = rs.Fields(\"ApMaterno\") & \"\"\n        txtNombre.Text = rs.Fields(\"Nombre\") & \"\"\n        txtRFC.Text = rs.Fields(\"RFC\") & \"\"\n        txtCURP.Text = rs.Fields(\"CURP\") & \"\"\n        txtAntiguedad.Text = rs.Fields(\"Antiguedad\") & \"\"\n        txtPuesto.Text = rs.Fields(\"Puesto\") & \"\"\n        txtHorasTrabajadas.Text = rs.Fields(\"HorasTrabajadas\") & \"\"\n        txtPrecioHora.Text = rs.Fields(\"PrecioHora\") & \"\"\n        CalcularSueldo\n        lblStatus.Caption = \" Expediente \" & rs.AbsolutePosition & \" de \" & rs.RecordCount & \" | Empleado: \" & txtNombre.Text & \" \" & txtApPaterno.Text\n    End If\nEnd Sub\n\nPrivate Sub CalcularSueldo()\n    On Error Resume Next\n    Dim horas As Double\n    Dim precio As Double\n    Dim hNormales As Double\n    Dim hExtras As Double\n    Dim pagoNormal As Double\n    Dim pagoExtra As Double\n    Dim sueldoBase As Double\n    Dim bonoAntig As Double\n    Dim anios As Double\n    Dim sueldoB As Double\n    Dim imss As Double\n    Dim ispt As Double\n    Dim fondoAhorro As Double\n    Dim totalDed As Double\n    Dim sueldoN As Double\n\n    horas = Val(txtHorasTrabajadas.Text)\n    precio = Val(txtPrecioHora.Text)\n    anios = Val(txtAntiguedad.Text)\n\n    If horas > 40 Then\n        hNormales = 40\n        hExtras = horas - 40\n    Else\n        hNormales = horas\n        hExtras = 0\n    End If\n\n    pagoNormal = hNormales * precio\n    pagoExtra = hExtras * (precio * 2)\n    sueldoBase = pagoNormal + pagoExtra\n\n    bonoAntig = sueldoBase * (anios * 0.025)\n    sueldoB = sueldoBase + bonoAntig\n\n    imss = sueldoB * 0.05\n    ispt = sueldoB * 0.045\n    fondoAhorro = sueldoB * 0.02\n    totalDed = imss + ispt + fondoAhorro\n    sueldoN = sueldoB - totalDed\n\n    txtHorasExtras.Text = Format(pagoExtra, \"$#,##0.00\") & \" (\" & hExtras & \" hrs)\"\n    txtBonoAntiguedad.Text = Format(bonoAntig, \"$#,##0.00\")\n    txtSueldoBruto.Text = Format(sueldoB, \"0.00\")\n    txtIMSS.Text = Format(imss, \"0.00\")\n    txtISPT.Text = Format(ispt, \"0.00\")\n    txtFondoAhorro.Text = Format(fondoAhorro, \"0.00\")\n    txtTotalDeducciones.Text = Format(totalDed, \"0.00\")\n    txtSueldoNeto.Text = Format(sueldoN, \"0.00\")\nEnd Sub\n\nPrivate Sub cmdCalcular_Click()\n    If Trim(txtHorasTrabajadas.Text) = \"\" Or Trim(txtPrecioHora.Text) = \"\" Then\n        MsgBox \"Por favor ingrese las Horas Trabajadas y el Precio por Hora.\", vbExclamation, \"Datos Requeridos\"\n        Exit Sub\n    End If\n    CalcularSueldo\n    MsgBox \"Cálculo de Nómina Detallado Realizado:\" & vbCrLf & _\n           \"------------------------------------------\" & vbCrLf & _\n           \"Sueldo Bruto Total: $\" & txtSueldoBruto.Text & vbCrLf & _\n           \"Deducción IMSS (5.0%): -$\" & txtIMSS.Text & vbCrLf & _\n           \"Deducción ISPT/ISR (4.5%): -$\" & txtISPT.Text & vbCrLf & _\n           \"Fondo de Ahorro (2.0%): -$\" & txtFondoAhorro.Text & vbCrLf & _\n           \"Total Retenciones: -$\" & txtTotalDeducciones.Text & vbCrLf & _\n           \"------------------------------------------\" & vbCrLf & _\n           \"SUELDO NETO A PAGAR: $\" & txtSueldoNeto.Text, vbInformation, \"Liquidación de Nómina\"\nEnd Sub\n\nPrivate Sub txtHorasTrabajadas_Change()\n    CalcularSueldo\nEnd Sub\n\nPrivate Sub txtPrecioHora_Change()\n    CalcularSueldo\nEnd Sub\n\nPrivate Sub txtAntiguedad_Change()\n    CalcularSueldo\nEnd Sub\n\nPrivate Sub cmdGuardar_Click()\n    On Error GoTo ErrGuardar\n    CalcularSueldo\n\n    If Trim(txtApPaterno.Text) = \"\" Or Trim(txtNombre.Text) = \"\" Then\n        MsgBox \"Ingrese al menos Apellido Paterno y Nombre del empleado.\", vbExclamation, \"Datos Faltantes\"\n        txtApPaterno.SetFocus\n        Exit Sub\n    End If\n\n    rs.AddNew\n    rs.Fields(\"ApPaterno\") = txtApPaterno.Text\n    rs.Fields(\"ApMaterno\") = txtApMaterno.Text\n    rs.Fields(\"Nombre\") = txtNombre.Text\n    rs.Fields(\"RFC\") = txtRFC.Text\n    rs.Fields(\"CURP\") = txtCURP.Text\n    rs.Fields(\"Antiguedad\") = txtAntiguedad.Text\n    rs.Fields(\"Puesto\") = txtPuesto.Text\n    rs.Fields(\"HorasTrabajadas\") = Val(txtHorasTrabajadas.Text)\n    rs.Fields(\"PrecioHora\") = Val(txtPrecioHora.Text)\n    rs.Fields(\"SueldoBruto\") = Val(txtSueldoBruto.Text)\n    rs.Fields(\"IMSS\") = Val(txtIMSS.Text)\n    rs.Fields(\"ISPT\") = Val(txtISPT.Text)\n    rs.Fields(\"SueldoNeto\") = Val(txtSueldoNeto.Text)\n    rs.Update\n\n    lblStatus.Caption = \" Registro guardado con éxito. Total registros: \" & rs.RecordCount\n    MsgBox \"Expediente de nómina guardado exitosamente en la base de datos.\", vbInformation, \"Registro Exitoso\"\n    Exit Sub\n\nErrGuardar:\n    MsgBox \"Error al guardar registro: \" & Err.Description, vbCritical, \"Error\"\nEnd Sub\n\nPrivate Sub cmdNuevo_Click()\n    LimpiarCampos\n    txtApPaterno.SetFocus\nEnd Sub\n\nPrivate Sub LimpiarCampos()\n    txtApPaterno.Text = \"\"\n    txtApMaterno.Text = \"\"\n    txtNombre.Text = \"\"\n    txtRFC.Text = \"\"\n    txtCURP.Text = \"\"\n    txtAntiguedad.Text = \"\"\n    txtPuesto.Text = \"\"\n    txtHorasTrabajadas.Text = \"\"\n    txtPrecioHora.Text = \"\"\n    txtHorasExtras.Text = \"$0.00\"\n    txtBonoAntiguedad.Text = \"$0.00\"\n    txtSueldoBruto.Text = \"0.00\"\n    txtIMSS.Text = \"0.00\"\n    txtISPT.Text = \"0.00\"\n    txtFondoAhorro.Text = \"0.00\"\n    txtTotalDeducciones.Text = \"0.00\"\n    txtSueldoNeto.Text = \"0.00\"\n    lblStatus.Caption = \" Modo captura: Ingrese los datos del nuevo empleado.\"\nEnd Sub\n\nPrivate Function ConstruirRecibo() As String\n    CalcularSueldo\n    Dim r As String\n    r = \"==========================================================\" & vbCrLf\n    r = r & \"             RECIBO EMPRESARIAL DE LIQUIDACION             \" & vbCrLf\n    r = r & \"==========================================================\" & vbCrLf\n    r = r & \"EMPLEADO: \" & txtNombre.Text & \" \" & txtApPaterno.Text & \" \" & txtApMaterno.Text & vbCrLf\n    r = r & \"RFC:      \" & txtRFC.Text & \"   CURP: \" & txtCURP.Text & vbCrLf\n    r = r & \"PUESTO:   \" & txtPuesto.Text & \"   ANTIGUEDAD: \" & txtAntiguedad.Text & \" años\" & vbCrLf\n    r = r & \"----------------------------------------------------------\" & vbCrLf\n    r = r & \"PERCEPCIONES ORDINARIAS Y EXTRAORDINARIAS:\" & vbCrLf\n    r = r & \"  Horas Trabajadas:             \" & txtHorasTrabajadas.Text & \" hrs\" & vbCrLf\n    r = r & \"  Precio por Hora:              $\" & txtPrecioHora.Text & vbCrLf\n    r = r & \"  Horas Extras (200% >40hrs):   \" & txtHorasExtras.Text & vbCrLf\n    r = r & \"  Bono por Antigüedad:          \" & txtBonoAntiguedad.Text & vbCrLf\n    r = r & \"  SUELDO BRUTO TOTAL:           $\" & txtSueldoBruto.Text & vbCrLf\n    r = r & \"----------------------------------------------------------\" & vbCrLf\n    r = r & \"DEDUCCIONES Y RETENCIONES FISCALES:\" & vbCrLf\n    r = r & \"  Seguridad Social IMSS (5.0%): -$\" & txtIMSS.Text & vbCrLf\n    r = r & \"  Impuesto ISPT/ISR (4.5%):     -$\" & txtISPT.Text & vbCrLf\n    r = r & \"  Fondo de Ahorro (2.0%):       -$\" & txtFondoAhorro.Text & vbCrLf\n    r = r & \"  TOTAL DEDUCCIONES:            -$\" & txtTotalDeducciones.Text & vbCrLf\n    r = r & \"==========================================================\" & vbCrLf\n    r = r & \"SUELDO NETO EFECTIVO A PAGAR:   $\" & txtSueldoNeto.Text & vbCrLf\n    r = r & \"==========================================================\"\n    ConstruirRecibo = r\nEnd Function\n\nPrivate Sub cmdRecibo_Click()\n    If Val(txtSueldoNeto.Text) = 0 Then\n        MsgBox \"Debe capturar horas y precio para emitir el recibo.\", vbExclamation, \"Aviso\"\n        Exit Sub\n    End If\n    Dim doc As String\n    doc = ConstruirRecibo\n    Clipboard.Clear\n    Clipboard.SetText doc\n    MsgBox doc & vbCrLf & vbCrLf & \"[Copiado automáticamente al Portapapeles de Windows]\", vbInformation, \"Recibo Oficial Emitido\"\nEnd Sub\n\nPrivate Sub cmdCopiarRecibo_Click()\n    cmdRecibo_Click\nEnd Sub\n\nPrivate Sub cmdEstadisticas_Click()\n    On Error Resume Next\n    Dim rsTemp As Recordset\n    Set rsTemp = New Recordset\n    rsTemp.Open \"SELECT * FROM Nomina\", conn, adOpenStatic, adLockReadOnly\n\n    If rsTemp.BOF And rsTemp.EOF Then\n        MsgBox \"No existen registros en la base de datos para generar estadísticas.\", vbInformation, \"Estadísticas\"\n        rsTemp.Close\n        Exit Sub\n    End If\n\n    Dim totalNomina As Double\n    Dim count As Long\n    Dim maxSueldo As Double\n    Dim maxNombre As String\n    Dim minSueldo As Double\n    Dim minNombre As String\n\n    minSueldo = 999999999\n\n    Do While Not rsTemp.EOF\n        Dim sNeto As Double\n        sNeto = Val(rsTemp.Fields(\"SueldoNeto\"))\n        totalNomina = totalNomina + sNeto\n        count = count + 1\n\n        If sNeto > maxSueldo Then\n            maxSueldo = sNeto\n            maxNombre = rsTemp.Fields(\"Nombre\") & \" \" & rsTemp.Fields(\"ApPaterno\")\n        End If\n\n        If sNeto < minSueldo Then\n            minSueldo = sNeto\n            minNombre = rsTemp.Fields(\"Nombre\") & \" \" & rsTemp.Fields(\"ApPaterno\")\n        End If\n\n        rsTemp.MoveNext\n    Loop\n    rsTemp.Close\n\n    Dim promedio As Double\n    If count > 0 Then promedio = totalNomina / count\n\n    MsgBox \"ESTADÍSTICAS GLOBALES DE NÓMINA:\" & vbCrLf & _\n           \"====================================\" & vbCrLf & _\n           \"Total Empleados Registrados: \" & count & vbCrLf & _\n           \"Desembolso Total Nómina: $\" & Format(totalNomina, \"#,##0.00\") & vbCrLf & _\n           \"Salario Promedio Neto: $\" & Format(promedio, \"#,##0.00\") & vbCrLf & _\n           \"------------------------------------\" & vbCrLf & _\n           \"Mayor Salario Neto: $\" & Format(maxSueldo, \"#,##0.00\") & \" (\" & maxNombre & \")\" & vbCrLf & _\n           \"Menor Salario Neto: $\" & Format(minSueldo, \"#,##0.00\") & \" (\" & minNombre & \")\", vbInformation, \"Auditoría de Nómina\"\nEnd Sub\n\nPrivate Sub cmdBuscar_Click()\n    On Error Resume Next\n    Dim filtro As String\n    filtro = Trim(txtBuscar.Text)\n    If filtro = \"\" Then\n        MsgBox \"Ingrese un RFC o Apellido para buscar.\", vbExclamation, \"Búsqueda\"\n        Exit Sub\n    End If\n\n    rs.MoveFirst\n    Dim encontrado As Boolean\n    encontrado = False\n\n    Do While Not rs.EOF\n        If InStr(1, rs.Fields(\"RFC\") & \"\", filtro, vbTextCompare) > 0 Or _\n           InStr(1, rs.Fields(\"ApPaterno\") & \"\", filtro, vbTextCompare) > 0 Or _\n           InStr(1, rs.Fields(\"Nombre\") & \"\", filtro, vbTextCompare) > 0 Then\n            encontrado = True\n            CargarRegistroActual\n            MsgBox \"Empleado encontrado: \" & rs.Fields(\"Nombre\") & \" \" & rs.Fields(\"ApPaterno\"), vbInformation, \"Resultado de Búsqueda\"\n            Exit Do\n        End If\n        rs.MoveNext\n    Loop\n\n    If Not encontrado Then\n        MsgBox \"No se encontró ningún empleado con el término: \" & filtro, vbExclamation, \"No Encontrado\"\n        rs.MoveFirst\n        CargarRegistroActual\n    End If\nEnd Sub\n\nPrivate Sub cmdPrimero_Click()\n    On Error Resume Next\n    If Not (rs.BOF Or rs.EOF) Then\n        rs.MoveFirst\n        CargarRegistroActual\n    End If\nEnd Sub\n\nPrivate Sub cmdUltimo_Click()\n    On Error Resume Next\n    If Not (rs.BOF Or rs.EOF) Then\n        rs.MoveLast\n        CargarRegistroActual\n    End If\nEnd Sub\n\nPrivate Sub cmdAnterior_Click()\n    On Error Resume Next\n    If Not (rs.BOF Or rs.EOF) Then\n        rs.MovePrevious\n        If rs.BOF Then\n            rs.MoveFirst\n            MsgBox \"Se encuentra en el primer registro.\", vbInformation, \"Inicio de Expedientes\"\n        End If\n        CargarRegistroActual\n    End If\nEnd Sub\n\nPrivate Sub cmdSiguiente_Click()\n    On Error Resume Next\n    If Not (rs.BOF Or rs.EOF) Then\n        rs.MoveNext\n        If rs.EOF Then\n            rs.MoveLast\n            MsgBox \"Se encuentra en el último registro.\", vbInformation, \"Fin de Expedientes\"\n        End If\n        CargarRegistroActual\n    End If\nEnd Sub\n\nPrivate Sub cmdSalir_Click()\n    If MsgBox(\"¿Desea cerrar el Sistema de Gestión de Nómina?\", vbQuestion + vbYesNo, \"Salir\") = vbYes Then\n        Unload Me\n    End If\nEnd Sub"
        }
