          "codigo": "Option Explicit\nPrivate Sub cmdCapturar_Click()\nDim sNombre As String, sApellido As String, sAnio As String\nDim sCodNom As String, sCodApe As String, sCodAnio As String\nDim sHashID As String\nDim iAnioNac As Integer, iEdad As Integer\nDim iArchivo As Integer\nsNombre = InputBox(\"Ingrese su nombre de pila:\", \"Registro de Identidad\", \"Carlos\")\nIf Len(Trim(sNombre)) = 0 Then Exit Sub\nsApellido = InputBox(\"Ingrese su apellido paterno:\", \"Registro de Identidad\", \"Hernandez\")\nIf Len(Trim(sApellido)) = 0 Then Exit Sub\nsAnio = InputBox(\"Ingrese su ano de nacimiento (ej. 2004):\", \"Ano de Nacimiento\", \"2004\")\nIf Len(Trim(sAnio)) = 0 Then Exit Sub\niAnioNac = Val(sAnio)\nIf iAnioNac < 1920 Or iAnioNac > Year(Date) Then\nMsgBox \"Ano de nacimiento fuera del rango valido.\", vbExclamation, \"Validacion\"\nExit Sub\nEnd If\nsCodNom = UCase(Left$(Trim(sNombre), 3))\nsCodApe = UCase(Right$(Trim(sApellido), 3))\nsCodAnio = Right$(Trim(sAnio), 2)\nsHashID = \"ID-\" & sCodNom & \"-\" & sCodApe & sCodAnio\niEdad = Year(Date) - iAnioNac\ntxtCodigoID.Text = sHashID\ntxtEdadCalculada.Text = iEdad & \" anos cumplidos (o por cumplir este ano)\"\ntxtMensajeRegistro.Text = \"Credencial expedida con exito para \" & Trim(sNombre) & \" \" & Trim(sApellido)\nOn Error Resume Next\niArchivo = FreeFile\nOpen App.Path & \"\\registro_credenciales.txt\" For Append As #iArchivo\nPrint #iArchivo, \"FECHA: \" & Now & \" | HASH: \" & sHashID & \" | NOMBRE: \" & sNombre & \" \" & sApellido & \" | EDAD: \" & iEdad\nClose #iArchivo\nEnd Sub\nPrivate Sub cmdLimpiar_Click()\ntxtCodigoID.Text = \"\"\ntxtEdadCalculada.Text = \"\"\ntxtMensajeRegistro.Text = \"\"\nEnd Sub\nPrivate Sub cmdSalir_Click()\nUnload Me\nEnd Sub"
