      "proceso_1": {
        "nombre": "Seleccionar Tarjeta (cmdCarta_Click)",
        "pseudocodigo": "Inicio cmdCarta_Click(Indice)\n    Si cartasVolteadas = 0 Entonces\n        primeraCarta <- Indice\n        MostrarImagen(Indice)\n        cartasVolteadas <- 1\n    Sino Si cartasVolteadas = 1 Y Indice <> primeraCarta Entonces\n        segundaCarta <- Indice\n        MostrarImagen(Indice)\n        cartasVolteadas <- 2\n        TimerPausa.Enabled <- Verdadero\n    FinSi\nFin cmdCarta_Click"
      },
      "proceso_2": {
        "nombre": "Evaluación del Par (TimerPausa_Timer)",
        "pseudocodigo": "Inicio TimerPausa_Timer\n    TimerPausa.Enabled <- Falso\n    Si valorCarta(primeraCarta) = valorCarta(segundaCarta) Entonces\n        paresEncontrados <- paresEncontrados + 1\n        cmdCarta(primeraCarta).Enabled <- Falso\n        cmdCarta(segundaCarta).Enabled <- Falso\n    Sino\n        OcultarImagen(primeraCarta)\n        OcultarImagen(segundaCarta)\n    FinSi\n    cartasVolteadas <- 0\nFin TimerPausa_Timer"
      },
      "total_archivos": 6,
      "archivos_codigo": [
        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\n\nPublic ContadorSegundos As Integer\nPublic ContadorMinutos As Integer\nPublic ContadorHoras As Integer\nPublic NumeroAciertos As Integer\nPublic NumeroFallos As Integer\nPublic NumeroParejas As Integer\nPublic ImagenNumero1 As Integer\nPublic ImagenNumero2 As Integer\nPrivate PermisoBorrar As Boolean\nPrivate PrimeraUbicacion(1, 2) As Integer\nPrivate SegundaUbicacion(1, 2) As Integer\nPrivate MatrizMemoria(4, 5) As Integer\nPrivate MatrizAciertos(4, 5) As Boolean\nDim Puntos As Integer\nDim enPista As Boolean\nDim tiempoPista As Integer\n\nPrivate Sub Command1_Click()\n    Dim i As Integer, j As Integer\n    NumeroAciertos = 0\n    NumeroFallos = 0\n    NumeroParejas = 0\n    ImagenNumero1 = 0\n    ImagenNumero2 = 0\n    Puntos = 0\n    ContadorHoras = 0\n    ContadorMinutos = 0\n    ContadorSegundos = 0\n    enPista = False\n    \n    For i = 0 To 3\n        For j = 0 To 4\n            MatrizAciertos(i, j) = False\n        Next j\n    Next i\n    \n    PintarInterrogantes\n    EstablecerMatrizDeImagenes\n    \n    Timer1.Enabled = True\n    LblTiempo.Caption = \"0:0:0\"\n    LblAciertos.Caption = \"Correct: 0\"\n    LblFallos.Caption = \"Incorrect: 0\"\n    LblPuntos.Caption = \"0\"\n    lblPrecision.Caption = \"Precision: 100%\"\nEnd Sub\n\nPrivate Sub Form_Load()\n    Me.BackColor = &H1E1814\n    Command1_Click\nEnd Sub\n\nPrivate Sub cmdPista_Click()\n    If Not Timer1.Enabled Or enPista Then Exit Sub\n    Dim i As Integer, j As Integer, idx As Integer\n    enPista = True\n    Puntos = Puntos - 150\n    If Puntos < 0 Then Puntos = 0\n    LblPuntos.Caption = Puntos\n    \n    idx = 0\n    For i = 0 To 3\n        For j = 0 To 4\n            Imagen(idx).Picture = LoadPicture(ObtenerRuta(\"Imagen \" & MatrizMemoria(i, j) & \".jpg\"))\n            idx = idx + 1\n        Next j\n    Next i\n    Beep\nEnd Sub\n\nPrivate Function ObtenerRuta(nombreArchivo As String) As String\n    Dim r1 As String, r2 As String\n    r1 = App.Path & \"\\Imagenes\\\" & nombreArchivo\n    r2 = App.Path & \"\\\" & nombreArchivo\n    If Dir(r1) <> \"\" Then\n        ObtenerRuta = r1\n    ElseIf Dir(r2) <> \"\" Then\n        ObtenerRuta = r2\n    Else\n        ObtenerRuta = \"\"\n    End If\nEnd Function\n\nPrivate Sub PintarTapa(Index As Integer)\n    Dim ruta As String\n    ruta = ObtenerRuta(\"Tapa.jpg\")\n    If ruta <> \"\" Then\n        Imagen(Index).Picture = LoadPicture(ruta)\n    Else\n        Imagen(Index).Cls\n    End If\nEnd Sub\n\nPrivate Sub Imagen_Click(Index As Integer)\n    If Not Timer1.Enabled Then Exit Sub\n    If enPista Then\n        enPista = False\n        PintarInterrogantes\n        Exit Sub\n    End If\n    \n    Dim X As Integer, Y As Integer\n    X = Index Mod 5\n    Y = Index \\ 5\n    \n    If MatrizAciertos(Y, X) Then Exit Sub\n    \n    If PermisoBorrar Then\n        PintarTapa PrimeraUbicacion(0, 0) * 5 + PrimeraUbicacion(0, 1)\n        PintarTapa SegundaUbicacion(0, 0) * 5 + SegundaUbicacion(0, 1)\n        PermisoBorrar = False\n    End If\n    \n    If ImagenNumero1 = 0 Then\n        ImagenNumero1 = MatrizMemoria(Y, X)\n        PrimeraUbicacion(0, 0) = Y\n        PrimeraUbicacion(0, 1) = X\n        Imagen(Index).Picture = LoadPicture(ObtenerRuta(\"Imagen \" & ImagenNumero1 & \".jpg\"))\n        Beep\n    ElseIf ImagenNumero2 = 0 Then\n        If PrimeraUbicacion(0, 0) = Y And PrimeraUbicacion(0, 1) = X Then Exit Sub\n        ImagenNumero2 = MatrizMemoria(Y, X)\n        SegundaUbicacion(0, 0) = Y\n        SegundaUbicacion(0, 1) = X\n        Imagen(Index).Picture = LoadPicture(ObtenerRuta(\"Imagen \" & ImagenNumero2 & \".jpg\"))\n        CompararImagenes ImagenNumero1, ImagenNumero2\n    End If\nEnd Sub\n\nPrivate Sub CompararImagenes(Valor1 As Integer, Valor2 As Integer)\n    If Valor1 = Valor2 Then\n        Puntos = Puntos + 500\n        NumeroAciertos = NumeroAciertos + 1\n        LblAciertos.Caption = \"Correct: \" & NumeroAciertos\n        MatrizAciertos(PrimeraUbicacion(0, 0), PrimeraUbicacion(0, 1)) = True\n        MatrizAciertos(SegundaUbicacion(0, 0), SegundaUbicacion(0, 1)) = True\n        Beep\n        PermisoBorrar = False\n    Else\n        Puntos = Puntos - 100\n        If Puntos < 0 Then Puntos = 0\n        NumeroFallos = NumeroFallos + 1\n        LblFallos.Caption = \"Incorrect: \" & NumeroFallos\n        PermisoBorrar = True\n    End If\n    \n    LblPuntos.Caption = Puntos\n    ImagenNumero1 = 0\n    ImagenNumero2 = 0\n    \n    Dim totalIntentos As Integer\n    totalIntentos = NumeroAciertos + NumeroFallos\n    If totalIntentos > 0 Then\n        lblPrecision.Caption = \"Precision: \" & Format$((NumeroAciertos / totalIntentos) * 100, \"0\") & \"%\"\n    End If\n    \n    If NumeroAciertos = 10 Then\n        Timer1.Enabled = False\n        MsgBox \"ENHORABUENA! Has completado el Memorama Cyberpunk con exito.\" & vbCrLf & \"Puntos Finales: \" & Puntos & vbCrLf & \"Tiempo: \" & LblTiempo.Caption, vbInformation, \"Victoria\"\n    End If\nEnd Sub\n\nPrivate Sub PintarInterrogantes()\n    Dim i As Integer\n    For i = 0 To 19\n        PintarTapa i\n    Next i\nEnd Sub\n\nPrivate Sub Timer1_Timer()\n    ContadorSegundos = ContadorSegundos + 1\n    If ContadorSegundos = 60 Then\n        ContadorSegundos = 0\n        ContadorMinutos = ContadorMinutos + 1\n        If ContadorMinutos = 60 Then\n            ContadorMinutos = 0\n            ContadorHoras = ContadorHoras + 1\n        End If\n    End If\n    LblTiempo.Caption = ContadorHoras & \":\" & ContadorMinutos & \":\" & ContadorSegundos\nEnd Sub\n\nPrivate Sub EstablecerMatrizDeImagenes()\n    Dim cartas(19) As Integer\n    Dim i As Integer, r As Integer, temp As Integer\n    Randomize\n    \n    For i = 0 To 9\n        cartas(i * 2) = i + 1\n        cartas(i * 2 + 1) = i + 1\n    Next i\n    \n    For i = 0 To 19\n        r = Int(Rnd * 20)\n        temp = cartas(i)\n        cartas(i) = cartas(r)\n        cartas(r) = temp\n    Next i\n    \n    Dim idx As Integer\n    idx = 0\n    Dim f As Integer, c As Integer\n    For f = 0 To 3\n        For c = 0 To 4\n            MatrizMemoria(f, c) = cartas(idx)\n            idx = idx + 1\n        Next c\n    Next f\nEnd Sub"
        }
      ]
