        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\nPrivate Sub Form_Load()\nNavegarURL txtDireccion.Text\nEnd Sub\nPrivate Sub cmdAtras_Click()\nOn Error Resume Next\nWebBrowser1.GoBack\nlblStatus.Caption = \"Retrocediendo pagina...\"\nEnd Sub\nPrivate Sub cmdAdelante_Click()\nOn Error Resume Next\nWebBrowser1.GoForward\nlblStatus.Caption = \"Avanzando pagina...\"\nEnd Sub\nPrivate Sub cmdRecargar_Click()\nOn Error Resume Next\nWebBrowser1.Refresh\nlblStatus.Caption = \"Actualizando contenido...\"\nEnd Sub\nPrivate Sub cmdInicio_Click()\ntxtDireccion.Text = \"https://www.unam.mx\"\nNavegarURL txtDireccion.Text\nEnd Sub\nPrivate Sub cmdNavegar_Click()\nNavegarURL txtDireccion.Text\nEnd Sub\nPrivate Sub cmdSalir_Click()\nUnload Me\nEnd Sub\nPrivate Sub txtDireccion_KeyPress(KeyAscii As Integer)\nIf KeyAscii = 13 Then\nKeyAscii = 0\ncmdNavegar_Click\nEnd If\nEnd Sub\nPrivate Sub cmdPortalYahoo_Click()\ntxtDireccion.Text = \"https://www.yahoo.com\"\nNavegarURL txtDireccion.Text\nEnd Sub\nPrivate Sub cmdPortalUNAM_Click()\ntxtDireccion.Text = \"https://www.unam.mx\"\nNavegarURL txtDireccion.Text\nEnd Sub\nPrivate Sub cmdPortalFESC_Click()\ntxtDireccion.Text = \"https://www.cuautitlan.unam.mx\"\nNavegarURL txtDireccion.Text\nEnd Sub\nPrivate Sub cmdPortalDGAE_Click()\ntxtDireccion.Text = \"https://cuautitlan.dgae.unam.mx\"\nNavegarURL txtDireccion.Text\nEnd Sub\nPrivate Sub cmdPortalWiki_Click()\ntxtDireccion.Text = \"https://es.wikipedia.org\"\nNavegarURL txtDireccion.Text\nEnd Sub\nPrivate Sub NavegarURL(ByVal sDestino As String)\nDim sURL As String\nsURL = Trim$(sDestino)\nIf Len(sURL) = 0 Then Exit Sub\nIf LCase$(Left$(sURL, 7)) <> \"http://\" And LCase$(Left$(sURL, 8)) <> \"https://\" Then\nsURL = \"https://\" & sURL\nEnd If\ntxtDireccion.Text = sURL\nlblStatus.Caption = \"Conectando a: \" & sURL & \"...\"\nOn Error Resume Next\nWebBrowser1.Navigate2 sURL\nEnd Sub\nPrivate Sub WebBrowser1_StatusTextChange(ByVal Text As String)\nIf Len(Trim$(Text)) > 0 Then\nlblStatus.Caption = Text\nElse\nlblStatus.Caption = \"Listo\"\nEnd If\nEnd Sub\nPrivate Sub WebBrowser1_TitleChange(ByVal Text As String)\nIf Len(Trim$(Text)) > 0 Then\nMe.Caption = Text & \" - Nexus Web Explorer [Version B]\"\nEnd If\nEnd Sub\nPrivate Sub WebBrowser1_NavigateComplete2(ByVal pDisp As Object, URL As Variant)\nOn Error Resume Next\ntxtDireccion.Text = CStr(URL)\nIf InStr(1, LCase$(CStr(URL)), \"https://\") > 0 Then\nlblSeguridad.Caption = \"[ SSL / HTTPS Activo ]\"\nlblSeguridad.ForeColor = &H0038BDF8&\nElse\nlblSeguridad.Caption = \"[ No seguro / HTTP ]\"\nlblSeguridad.ForeColor = &H000080FF&\nEnd If\nlblStatus.Caption = \"Pagina cargada exitosamente.\"\nEnd Sub\nPrivate Sub Form_Resize()\nOn Error Resume Next\nIf Me.ScaleWidth > 2000 And Me.ScaleHeight > 2500 Then\nWebBrowser1.Width = Me.ScaleWidth - 240\nWebBrowser1.Height = Me.ScaleHeight - picBarraNavegacion.Height - picStatusBar.Height - 120\nlblSeguridad.Left = Me.ScaleWidth - lblSeguridad.Width - 200\ntxtDireccion.Width = Me.ScaleWidth - txtDireccion.Left - cmdNavegar.Width - cmdSalir.Width - 300\ncmdNavegar.Left = txtDireccion.Left + txtDireccion.Width + 100\ncmdSalir.Left = cmdNavegar.Left + cmdNavegar.Width + 100\nEnd If\nEnd Sub"
        }
