          "archivo": "Form5.frm",
          "codigo": "Option Explicit\n\nDim rs As Recordset\n\nDim sellpoint As Connection\n\nDim pathBD As String\n\nPrivate Sub Command5_Click()\n\nrs.Close\n\nrs.Open \"select * from Productos where Prodcuto = '\" & Text3.Text & \"'\", sellpoint, adOpenDynamic, adLockOptimistic\n\n\n\nIf Not (rs.EOF And rs.BOF) Then\n\nText1.Text = rs.Fields(\"Prodcuto\")\n\nText2.Text = rs.Fields(\"Precio\")\n\nElse\n\nText3.Text = \"No se encontró registro\"\n\nText1.Text = \"\"\n\nText2.Text = \"\"\n\nEnd If\n\nrs.Close\n\nrs.Open \"select * from Productos\", sellpoint, adOpenDynamic, adLockOptimistic\n\nEnd Sub\n\n\n\nPrivate Sub Command7_Click()\n\nrs.Close\n\nrs.Open \"select * from Productos where Prodcuto = '\" & Text3.Text & \"'\", sellpoint, adOpenDynamic, adLockOptimistic\n\n\n\nIf Not (rs.EOF And rs.BOF) Then\n\n\n\nDo Until (rs.EOF Or rs.BOF)\n\nList1.AddItem (rs.Fields(\"Prodcuto\") & \" \" & rs.Fields(\"Precio\"))\n\nrs.MoveNext\n\nLoop\n\n\n\nElse\n\nText3.Text = \"No se encontró registro\"\n\nList1.Clear\n\nEnd If\n\nrs.Close\n\nrs.Open \"select * from Productos\", sellpoint, adOpenDynamic, adLockOptimistic\n\nEnd Sub\n\n\n\nPrivate Sub Command8_Click()\n\nList1.Clear\n\nEnd Sub\n\n\n\nPrivate Sub Form_Load()\n\nSet sellpoint = New Connection\n\nSet rs = New Recordset\n\n\n\npathBD = App.Path & \"\\sellpoint.mdb\"\n\n\n\nsellpoint.Open \"PROVIDER=Microsoft.Jet.OLEDB.4.0;Data Source=\" & pathBD & \";\"\n\nrs.Open \"select * from Productos\", sellpoint, adOpenDynamic, adLockOptimistic\n\n\n\nEnd Sub"
