          "archivo": "Form1.frm",
          "codigo": "Option Explicit\nDim modo24h As Boolean\nDim decimasTotal As Long\nDim cronoActivo As Boolean\nDim numVuelta As Integer\n\nPrivate Sub Form_Load()\n    modo24h = False\n    cronoActivo = False\n    decimasTotal = 0\n    numVuelta = 0\n    ActualizarReloj\nEnd Sub\n\nPrivate Sub TimerClock_Timer()\n    ActualizarReloj\nEnd Sub\n\nPrivate Sub ActualizarReloj()\n    If modo24h Then\n        lblHoraDigital.Caption = Format$(Now, \"HH:nn:ss\")\n    Else\n        lblHoraDigital.Caption = Format$(Now, \"hh:nn:ss AMPM\")\n    End If\n    lblFechaLarga.Caption = Format$(Now, \"dddd, d \\d\\e mmmm \\d\\e yyyy\")\nEnd Sub\n\nPrivate Sub cmdFormato_Click()\n    modo24h = Not modo24h\n    ActualizarReloj\nEnd Sub\n\nPrivate Sub cmdStartStop_Click()\n    If Not cronoActivo Then\n        cronoActivo = True\n        TimerCronometro.Enabled = True\n        cmdStartStop.Caption = \"Pausar\"\n    Else\n        cronoActivo = False\n        TimerCronometro.Enabled = False\n        cmdStartStop.Caption = \"Reanudar\"\n    End If\nEnd Sub\n\nPrivate Sub cmdResetCrono_Click()\n    cronoActivo = False\n    TimerCronometro.Enabled = False\n    decimasTotal = 0\n    numVuelta = 0\n    cmdStartStop.Caption = \"Iniciar\"\n    lblCronoDisplay.Caption = \"00:00:00.0\"\n    lstVueltas.Clear\nEnd Sub\n\nPrivate Sub cmdLap_Click()\n    If decimasTotal = 0 Then Exit Sub\n    numVuelta = numVuelta + 1\n    lstVueltas.AddItem \"Vuelta \" & Format$(numVuelta, \"00\") & \" -> \" & lblCronoDisplay.Caption, 0\nEnd Sub\n\nPrivate Sub TimerCronometro_Timer()\n    decimasTotal = decimasTotal + 1\n    Dim horas As Long, minutos As Long, segundos As Long, decimas As Long\n    decimas = decimasTotal Mod 10\n    segundos = (decimasTotal \\ 10) Mod 60\n    minutos = (decimasTotal \\ 600) Mod 60\n    horas = (decimasTotal \\ 36000)\n    lblCronoDisplay.Caption = Format$(horas, \"00\") & \":\" & Format$(minutos, \"00\") & \":\" & Format$(segundos, \"00\") & \".\" & decimas\nEnd Sub"
