      "archivos_codigo": [
        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\n\nPrivate Declare Function MessageBeep Lib \"user32\" (ByVal wType As Long) As Long\n\nDim TiempoRestante As Integer\nDim Puntos As Long\nDim Record As Long\nDim TirosTotales As Integer\nDim TirosAcertados As Integer\nDim VelX As Single, VelY As Single\nDim EnJuego As Boolean\n\nPrivate Sub Form_Load()\n    cboDificultad.AddItem \"Fácil\"\n    cboDificultad.AddItem \"Normal\"\n    cboDificultad.AddItem \"Difícil\"\n    cboDificultad.ListIndex = 1\n\n    DibujarDiana picDiana.ScaleWidth / 2, picDiana.ScaleHeight / 2\n    ReiniciarJuego\nEnd Sub\n\nPrivate Sub DibujarDiana(CentroX As Single, CentroY As Single)\n    picDiana.Cls\n    Dim R As Single\n    R = CentroX - 10\n\n\n    picDiana.FillStyle = 0\n    picDiana.FillColor = vbRed\n    picDiana.Circle (CentroX, CentroY), R, vbBlack\n\n\n    picDiana.FillColor = vbWhite\n    picDiana.Circle (CentroX, CentroY), R * 0.7, vbBlack\n\n\n    picDiana.FillColor = vbBlue\n    picDiana.Circle (CentroX, CentroY), R * 0.45, vbBlack\n\n\n    picDiana.FillColor = vbYellow\n    picDiana.Circle (CentroX, CentroY), R * 0.2, vbBlack\nEnd Sub\n\nPrivate Sub ReiniciarJuego()\n    TiempoRestante = 30\n    Puntos = 0\n    TirosTotales = 0\n    TirosAcertados = 0\n    EnJuego = False\n\n    lblTiempo.Caption = \"30s\"\n    lblPuntos.Caption = \"Puntos: 0\"\n    lblDisparos.Caption = \"Tiros: 0 / 0\"\n    lblPrecision.Caption = \"Precisión: 0%\"\n\n    tmrJuego.Enabled = False\n    tmrMovimiento.Enabled = False\n    cmdIniciar.Caption = \"INICIAR (30s)\"\nEnd Sub\n\nPrivate Sub cmdIniciar_Click()\n    If Not EnJuego Then\n        ReiniciarJuego\n        EnJuego = True\n\n\n        Select Case cboDificultad.ListIndex\n            Case 0: VelX = 40: VelY = 30\n            Case 1: VelX = 80: VelY = 60\n            Case 2: VelX = 140: VelY = 110\n        End Select\n\n        tmrJuego.Enabled = True\n        tmrMovimiento.Enabled = True\n        cmdIniciar.Caption = \"DETENER\"\n    Else\n        ReiniciarJuego\n    End If\nEnd Sub\n\nPrivate Sub tmrJuego_Timer()\n    TiempoRestante = TiempoRestante - 1\n    lblTiempo.Caption = TiempoRestante & \"s\"\n\n    If TiempoRestante <= 0 Then\n        tmrJuego.Enabled = False\n        tmrMovimiento.Enabled = False\n        EnJuego = False\n        cmdIniciar.Caption = \"JUGAR DE NUEVO\"\n\n        If Puntos > Record Then\n            Record = Puntos\n            lblRecord.Caption = \"Récord: \" & Record\n            MsgBox \"¡NUEVO RÉCORD! Lograste \" & Puntos & \" puntos con \" & lblPrecision.Caption & \".\", vbInformation, \"¡Felicidades!\"\n        Else\n            MsgBox \"¡Fin del Tiempo! Puntuación final: \" & Puntos & \" puntos.\", vbInformation, \"Tiempo Cumplido\"\n        End If\n    End If\nEnd Sub\n\nPrivate Sub tmrMovimiento_Timer()\n    Dim nuevoX As Single, nuevoY As Single\n    nuevoX = picDiana.Left + VelX\n    nuevoY = picDiana.Top + VelY\n\n    If nuevoX <= 0 Then\n        nuevoX = 0\n        VelX = -VelX\n    ElseIf nuevoX + picDiana.Width >= picEscenario.ScaleWidth Then\n        nuevoX = picEscenario.ScaleWidth - picDiana.Width\n        VelX = -VelX\n    End If\n\n    If nuevoY <= 0 Then\n        nuevoY = 0\n        VelY = -VelY\n    ElseIf nuevoY + picDiana.Height >= picEscenario.ScaleHeight Then\n        nuevoY = picEscenario.ScaleHeight - picDiana.Height\n        VelY = -VelY\n    End If\n\n    picDiana.Left = nuevoX\n    picDiana.Top = nuevoY\nEnd Sub\n\nPrivate Sub picDiana_MouseDown(Button As Integer, Shift As Integer, X As Single, Y As Single)\n    If Not EnJuego Then Exit Sub\n\n    TirosTotales = TirosTotales + 1\n    TirosAcertados = TirosAcertados + 1\n\n    Dim CentroX As Single, CentroY As Single\n    Dim dist As Single, Radio As Single\n    CentroX = picDiana.ScaleWidth / 2\n    CentroY = picDiana.ScaleHeight / 2\n    Radio = CentroX - 10\n\n    dist = Sqr((X - CentroX) ^ 2 + (Y - CentroY) ^ 2)\n\n    Dim pts As Integer\n    If dist <= Radio * 0.2 Then\n        pts = 100\n        Beep\n    ElseIf dist <= Radio * 0.45 Then\n        pts = 50\n    ElseIf dist <= Radio * 0.7 Then\n        pts = 25\n    Else\n        pts = 10\n    End If\n\n    Puntos = Puntos + pts\n    lblPuntos.Caption = \"Puntos: \" & Puntos\n    lblDisparos.Caption = \"Tiros: \" & TirosAcertados & \" / \" & TirosTotales\n    lblPrecision.Caption = \"Precisión: \" & Format((TirosAcertados / TirosTotales) * 100, \"0\") & \"%\"\n\n\n    picDiana.Left = Rnd * (picEscenario.ScaleWidth - picDiana.Width)\n    picDiana.Top = Rnd * (picEscenario.ScaleHeight - picDiana.Height)\nEnd Sub\n\nPrivate Sub picEscenario_MouseDown(Button As Integer, Shift As Integer, X As Single, Y As Single)\n    If Not EnJuego Then Exit Sub\n\n\n    TirosTotales = TirosTotales + 1\n    lblDisparos.Caption = \"Tiros: \" & TirosAcertados & \" / \" & TirosTotales\n    lblPrecision.Caption = \"Precisión: \" & Format((TirosAcertados / TirosTotales) * 100, \"0\") & \"%\"\nEnd Sub\n\nPrivate Sub cmdSalir_Click()\n    Unload Me\n    End\nEnd Sub"
        }
      ]
