        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\n\nDim SaldoActual As Double\nConst PIN_CORRECTO As String = \"1234\"\n\nPrivate Sub Form_Load()\n    SaldoActual = 15450#\n    fraLogin.Visible = True\n    fraPrincipal.Visible = False\n    txtPIN.Text = \"\"\n    ActualizarSaldo\n    lstHistorial.AddItem Format(Now, \"dd/mm/yyyy hh:nn:ss\") & \" - Inicio de Sistema. Saldo inicial: \" & Format(SaldoActual, \"$#,##0.00\")\nEnd Sub\n\nPrivate Sub ActualizarSaldo()\n    lblSaldo.Caption = \"Saldo Disponible: \" & Format(SaldoActual, \"$#,##0.00\") & \" MXN\"\nEnd Sub\n\nPrivate Sub cmdNum_Click(Index As Integer)\n    If Len(txtPIN.Text) < 4 Then\n        txtPIN.Text = txtPIN.Text & Index\n    End If\nEnd Sub\n\nPrivate Sub cmdBorrarPIN_Click()\n    txtPIN.Text = \"\"\nEnd Sub\n\nPrivate Sub cmdAceptarPIN_Click()\n    If txtPIN.Text = PIN_CORRECTO Then\n        fraLogin.Visible = False\n        fraPrincipal.Visible = True\n        txtPIN.Text = \"\"\n        lblDispensador.Caption = \"Billetes dispensados: Ninguno\"\n        MsgBox \"¡Bienvenido a su sesión bancaria!\", vbInformation, \"Acceso Autorizado\"\n    Else\n        MsgBox \"NIP incorrecto. Intente de nuevo.\", vbCritical, \"Error de Autenticación\"\n        txtPIN.Text = \"\"\n        txtPIN.SetFocus\n    End If\nEnd Sub\n\nPrivate Sub cmdRetiroRapido_Click(Index As Integer)\n    Dim montos(3) As Double\n    montos(0) = 100#\n    montos(1) = 200#\n    montos(2) = 500#\n    montos(3) = 1000#\n\n    ProcesarRetiro montos(Index)\nEnd Sub\n\nPrivate Sub cmdRetirar_Click()\n    If Trim(txtMonto.Text) = \"\" Or Not IsNumeric(txtMonto.Text) Then\n        MsgBox \"Introduce una cantidad válida a retirar.\", vbExclamation, \"Dato Inválido\"\n        Exit Sub\n    End If\n    ProcesarRetiro CDbl(txtMonto.Text)\nEnd Sub\n\nPrivate Sub ProcesarRetiro(Monto As Double)\n    If Monto <= 0 Then\n        MsgBox \"El monto a retirar debe ser mayor a cero.\", vbExclamation, \"Monto Inválido\"\n        Exit Sub\n    End If\n\n    If Monto Mod 50 <> 0 Then\n        MsgBox \"El cajero solo dispensa múltiplos de $50 pesos ($50, $100, $200, $500).\", vbExclamation, \"Denominación no disponible\"\n        Exit Sub\n    End If\n\n    If Monto > SaldoActual Then\n        MsgBox \"Fondos insuficientes. Su saldo disponible es: \" & Format(SaldoActual, \"$#,##0.00\"), vbCritical, \"Operación Denegada\"\n        Exit Sub\n    End If\n\n\n    Dim b500 As Integer, b200 As Integer, b100 As Integer, b50 As Integer\n    Dim resto As Double\n    resto = Monto\n\n    b500 = Int(resto / 500): resto = resto Mod 500\n    b200 = Int(resto / 200): resto = resto Mod 200\n    b100 = Int(resto / 100): resto = resto Mod 100\n    b50 = Int(resto / 50): resto = resto Mod 50\n\n    SaldoActual = SaldoActual - Monto\n    ActualizarSaldo\n\n    Dim desglose As String\n    desglose = \"Entregado: \" & Format(Monto, \"$#,##0.00\") & \" [\"\n    If b500 > 0 Then desglose = desglose & b500 & \" de $500, \"\n    If b200 > 0 Then desglose = desglose & b200 & \" de $200, \"\n    If b100 > 0 Then desglose = desglose & b100 & \" de $100, \"\n    If b50 > 0 Then desglose = desglose & b50 & \" de $50, \"\n    If Right(desglose, 2) = \", \" Then desglose = Left(desglose, Len(desglose) - 2)\n    desglose = desglose & \"]\"\n\n    lblDispensador.Caption = desglose\n    lstHistorial.AddItem Format(Now, \"hh:nn:ss\") & \" - RETIRO: -\" & Format(Monto, \"$#,##0.00\") & \" | Nuevo Saldo: \" & Format(SaldoActual, \"$#,##0.00\")\n    Beep\n    MsgBox \"Retiro exitoso. \" & vbCrLf & desglose & vbCrLf & \"No olvide retirar su dinero y comprobante.\", vbInformation, \"Retiro Completado\"\nEnd Sub\n\nPrivate Sub cmdDepositar_Click()\n    If Trim(txtMonto.Text) = \"\" Or Not IsNumeric(txtMonto.Text) Then\n        MsgBox \"Introduce una cantidad válida a depositar.\", vbExclamation, \"Dato Inválido\"\n        Exit Sub\n    End If\n\n    Dim Monto As Double\n    Monto = CDbl(txtMonto.Text)\n    If Monto <= 0 Then\n        MsgBox \"El monto a depositar debe ser mayor a cero.\", vbExclamation, \"Monto Inválido\"\n        Exit Sub\n    End If\n\n    SaldoActual = SaldoActual + Monto\n    ActualizarSaldo\n\n    lblDispensador.Caption = \"Depósito recibido: \" & Format(Monto, \"$#,##0.00\") & \" en efectivo.\"\n    lstHistorial.AddItem Format(Now, \"hh:nn:ss\") & \" - DEPÓSITO: +\" & Format(Monto, \"$#,##0.00\") & \" | Nuevo Saldo: \" & Format(SaldoActual, \"$#,##0.00\")\n    Beep\n    MsgBox \"Depósito acreditado inmediatamente a su cuenta.\", vbInformation, \"Depósito Exitoso\"\nEnd Sub\n\nPrivate Sub cmdSalirATM_Click()\n    MsgBox \"Gracias por utilizar Cajero Automático RED. Su tarjeta ha sido expulsada.\", vbInformation, \"Sesión Terminada\"\n    fraPrincipal.Visible = False\n    fraLogin.Visible = True\n    txtPIN.Text = \"\"\nEnd Sub"
        }
