          "archivo": "Form1.frm",
          "codigo": "Option Explicit\nPrivate Sub cmdBucleFor_Click()\nDim i As Integer\nlstResultados.Clear\nFor i = 1 To 15\nlstResultados.AddItem \"Indice \" & Format$(i, \"00\") & \" -> Muestra: \" & (i * 7)\nNext i\nCalcularEstadisticas\nEnd Sub\nPrivate Sub cmdBucleWhile_Click()\nDim valNum As Integer\nDim contador As Integer\nlstResultados.Clear\nvalNum = 2\ncontador = 1\nDo While valNum <= 30\nlstResultados.AddItem \"Paso \" & Format$(contador, \"00\") & \" -> Valor Par: \" & valNum\nvalNum = valNum + 2\ncontador = contador + 1\nLoop\nCalcularEstadisticas\nEnd Sub\nPrivate Sub cmdBucleUntil_Click()\nDim potencia As Long\nDim exp As Integer\nlstResultados.Clear\npotencia = 1\nexp = 0\nDo Until potencia > 1024\nlstResultados.AddItem \"2 ^ \" & exp & \" = \" & potencia\npotencia = potencia * 2\nexp = exp + 1\nLoop\nCalcularEstadisticas\nEnd Sub\nPrivate Sub CalcularEstadisticas()\nDim i As Integer, totalItems As Integer\nDim dblSuma As Double, dblMedia As Double\nDim dblMin As Double, dblMax As Double\nDim sLinea As String, posSep As Integer, dblVal As Double\ntotalItems = lstResultados.ListCount\nIf totalItems = 0 Then\nlblN.Caption = \"Elementos (N): 0\"\nlblSuma.Caption = \"Sumatoria Total: 0\"\nlblMinMax.Caption = \"Rango: Min = 0 | Max = 0\"\nlblPromedio.Caption = \"Media Aritmetica: 0.00\"\nExit Sub\nEnd If\ndblSuma = 0\nFor i = 0 To totalItems - 1\nsLinea = lstResultados.List(i)\nposSep = InStrRev(sLinea, \" \")\nIf posSep > 0 Then\ndblVal = Val(Mid$(sLinea, posSep + 1))\nElse\ndblVal = Val(sLinea)\nEnd If\ndblSuma = dblSuma + dblVal\nIf i = 0 Then\ndblMin = dblVal\ndblMax = dblVal\nElse\nIf dblVal < dblMin Then dblMin = dblVal\nIf dblVal > dblMax Then dblMax = dblVal\nEnd If\nNext i\ndblMedia = dblSuma / totalItems\nlblN.Caption = \"Elementos (N): \" & totalItems\nlblSuma.Caption = \"Sumatoria Total: \" & Format$(dblSuma, \"#,##0.00\")\nlblMinMax.Caption = \"Rango: Min = \" & dblMin & \" | Max = \" & dblMax\nlblPromedio.Caption = \"Media Aritmetica: \" & Format$(dblMedia, \"#,##0.00\")\nEnd Sub\nPrivate Sub cmdLimpiar_Click()\nlstResultados.Clear\nCalcularEstadisticas\nEnd Sub\nPrivate Sub cmdCerrar_Click()\nUnload Me\nEnd Sub"
