        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\nPrivate iTablero(8) As Integer\nPrivate iVacioIdx As Integer\nPrivate lMovimientos As Long\nPrivate lSegundos As Long\nPrivate bJuegoActivo As Boolean\nPrivate Sub Form_Load()\nReiniciarTablero\nEnd Sub\nPrivate Sub ReiniciarTablero()\nDim i As Integer\nFor i = 0 To 7\niTablero(i) = i + 1\nNext i\niTablero(8) = 0\niVacioIdx = 8\nlMovimientos = 0\nlSegundos = 0\nbJuegoActivo = False\nTimerJuego.Enabled = False\nlblMovimientos.Caption = \"Movimientos: 0\"\nlblCronometro.Caption = \"Tiempo: 00:00\"\nlblStatusJuego.Caption = \"Tablero resuelto. Presione 'Mezclar Tablero' para comenzar un nuevo reto.\"\nActualizarBotones\nEnd Sub\nPrivate Sub ActualizarBotones()\nDim i As Integer\nFor i = 0 To 8\nIf iTablero(i) = 0 Then\ncmdTile(i).Caption = \"\"\ncmdTile(i).Visible = False\nElse\ncmdTile(i).Caption = iTablero(i)\ncmdTile(i).Visible = True\ncmdTile(i).BackColor = &H00FFFFFF&\nEnd If\nNext i\nEnd Sub\nPrivate Sub cmdTile_Click(Index As Integer)\nIf EsMovimientoValido(Index, iVacioIdx) Then\nMoverPieza Index\nIf Not bJuegoActivo Then\nbJuegoActivo = True\nTimerJuego.Enabled = True\nEnd If\nVerificarVictoria\nEnd If\nEnd Sub\nPrivate Function EsMovimientoValido(ByVal pos As Integer, ByVal vacio As Integer) As Boolean\nDim f1 As Integer, c1 As Integer\nDim f2 As Integer, c2 As Integer\nf1 = pos \\ 3: c1 = pos Mod 3\nf2 = vacio \\ 3: c2 = vacio Mod 3\nIf (Abs(f1 - f2) = 1 And c1 = c2) Or (Abs(c1 - c2) = 1 And f1 = f2) Then\nEsMovimientoValido = True\nElse\nEsMovimientoValido = False\nEnd If\nEnd Function\nPrivate Sub MoverPieza(ByVal pos As Integer)\niTablero(iVacioIdx) = iTablero(pos)\niTablero(pos) = 0\niVacioIdx = pos\nlMovimientos = lMovimientos + 1\nlblMovimientos.Caption = \"Movimientos: \" & lMovimientos\nActualizarBotones\nEnd Sub\nPrivate Sub cmdMezclar_Click()\nDim n As Integer\nDim posValidas(3) As Integer, cantValidas As Integer\nDim p As Integer\nRandomize\nFor n = 1 To 50\ncantValidas = 0\nFor p = 0 To 8\nIf EsMovimientoValido(p, iVacioIdx) Then\nposValidas(cantValidas) = p\ncantValidas = cantValidas + 1\nEnd If\nNext p\nIf cantValidas > 0 Then\nDim sel As Integer\nsel = Int(Rnd * cantValidas)\niTablero(iVacioIdx) = iTablero(posValidas(sel))\niTablero(posValidas(sel)) = 0\niVacioIdx = posValidas(sel)\nEnd If\nNext n\nlMovimientos = 0\nlSegundos = 0\nbJuegoActivo = True\nTimerJuego.Enabled = True\nlblMovimientos.Caption = \"Movimientos: 0\"\nlblCronometro.Caption = \"Tiempo: 00:00\"\nlblStatusJuego.Caption = \"Tablero mezclado. Deslice las fichas para ordenar del 1 al 8.\"\nActualizarBotones\nEnd Sub\nPrivate Sub VerificarVictoria()\nDim i As Integer\nFor i = 0 To 7\nIf iTablero(i) <> i + 1 Then Exit Sub\nNext i\nIf iTablero(8) = 0 Then\nTimerJuego.Enabled = False\nbJuegoActivo = False\nlblStatusJuego.Caption = \"FELICIDADES: Rompecabezas completado con exito.\"\nMsgBox \"Excelente: Has resuelto el 8-Puzzle en \" & lMovimientos & \" movimientos y \" & lblCronometro.Caption & \".\", vbInformation, \"Victoria\"\nEnd If\nEnd Sub\nPrivate Sub TimerJuego_Timer()\nlSegundos = lSegundos + 1\nlblCronometro.Caption = \"Tiempo: \" & Format$(lSegundos \\ 60, \"00\") & \":\" & Format$(lSegundos Mod 60, \"00\")\nEnd Sub\nPrivate Sub cmdReiniciar_Click()\nReiniciarTablero\nEnd Sub\nPrivate Sub cmdSalir_Click()\nUnload Me\nEnd Sub"
        }
