        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\nDim quizA As Integer\nDim quizB As Integer\nDim aciertos As Integer\nDim errores As Integer\nDim racha As Integer\n\nPrivate Sub Form_Load()\n    Randomize\n    aciertos = 0\n    errores = 0\n    racha = 0\n    cmdGenerar_Click\n    cmdNuevoReto_Click\nEnd Sub\n\nPrivate Sub cmdGenerar_Click()\n    Dim n As Integer, lim As Integer, i As Integer\n    n = Val(txtNumero.Text)\n    lim = Val(txtLimite.Text)\n    If lim <= 0 Then lim = 10\n    lstTabla.Clear\n    lstTabla.AddItem \"--- TABLA DEL \" & n & \" ---\"\n    For i = 1 To lim\n        lstTabla.AddItem \" \" & n & \" x \" & Format$(i, \"@@\") & \" = \" & (n * i)\n    Next i\nEnd Sub\n\nPrivate Sub cmdPitagorica_Click()\n    Dim f As Integer, c As Integer\n    Dim linea As String\n    lstTabla.Clear\n    lstTabla.AddItem \"--- MATRIZ PITAGORICA (10x10) ---\"\n    For f = 1 To 10\n        linea = \"F\" & Format$(f, \"00\") & \": \"\n        For c = 1 To 10\n            linea = linea & Right$(\"   \" & (f * c), 4)\n        Next c\n        lstTabla.AddItem linea\n    Next f\nEnd Sub\n\nPrivate Sub cmdCopiarTabla_Click()\n    Dim i As Integer, s As String\n    s = \"\"\n    For i = 0 To lstTabla.ListCount - 1\n        s = s & lstTabla.List(i) & vbCrLf\n    Next i\n    Clipboard.Clear\n    Clipboard.SetText s\n    MsgBox \"Tabla copiada al portapapeles exitosamente.\", vbInformation, \"Copiar\"\nEnd Sub\n\nPrivate Sub cmdNuevoReto_Click()\n    quizA = Int(Rnd * 12) + 1\n    quizB = Int(Rnd * 12) + 1\n    lblPregunta.Caption = quizA & \" x \" & quizB & \" = ?\"\n    lblFeedback.Caption = \"Introduce tu respuesta y pulsa Comprobar\"\n    lblFeedback.ForeColor = &HE0E0E0\n    txtRespuesta.Text = \"\"\n    txtRespuesta.SetFocus\nEnd Sub\n\nPrivate Sub cmdResponder_Click()\n    Dim resp As Integer\n    resp = Val(txtRespuesta.Text)\n    If resp = (quizA * quizB) Then\n        aciertos = aciertos + 1\n        racha = racha + 1\n        Beep\n        lblFeedback.Caption = \"GENIAL! \" & quizA & \" x \" & quizB & \" = \" & (quizA * quizB)\n        lblFeedback.ForeColor = &HFF00&\n    Else\n        errores = errores + 1\n        racha = 0\n        lblFeedback.Caption = \"FALLASTE. \" & quizA & \" x \" & quizB & \" = \" & (quizA * quizB)\n        lblFeedback.ForeColor = &HFF&\n    End If\n    lblPuntos.Caption = \"Aciertos: \" & aciertos & \" | Errores: \" & errores & \" | Racha: x\" & racha\n    cmdNuevoReto_Click\nEnd Sub\n\nPrivate Sub txtRespuesta_KeyPress(KeyAscii As Integer)\n    If KeyAscii = 13 Then\n        KeyAscii = 0\n        cmdResponder_Click\n    End If\nEnd Sub"
        }
