        {
          "archivo": "Form1.frm",
          "codigo": "Option Explicit\nDim segTotal As Long\nDim activo As Boolean\n\nPrivate Sub Form_Load()\n    activo = False\n    segTotal = 1800\n    lblDisplayRestante.Caption = \"00:30:00\"\nEnd Sub\n\nPrivate Sub cmdPreset_Click(Index As Integer)\n    Select Case Index\n        Case 0\n            txtMinutos.Text = \"5\"\n        Case 1\n            txtMinutos.Text = \"15\"\n        Case 2\n            txtMinutos.Text = \"30\"\n        Case 3\n            txtMinutos.Text = \"60\"\n    End Select\n    txtMinutos_Change\nEnd Sub\n\nPrivate Sub txtMinutos_Change()\n    If Not activo Then\n        Dim m As Long\n        m = Val(txtMinutos.Text)\n        If m <= 0 Then m = 1\n        segTotal = m * 60\n        MostrarTiempo segTotal\n    End If\nEnd Sub\n\nPrivate Sub MostrarTiempo(ByVal s As Long)\n    Dim h As Long, mn As Long, sc As Long\n    sc = s Mod 60\n    mn = (s \\ 60) Mod 60\n    h = s \\ 3600\n    lblDisplayRestante.Caption = Format$(h, \"00\") & \":\" & Format$(mn, \"00\") & \":\" & Format$(sc, \"00\")\nEnd Sub\n\nPrivate Sub cmdIniciar_Click()\n    Dim m As Long\n    m = Val(txtMinutos.Text)\n    If m <= 0 Then\n        MsgBox \"Ingrese un tiempo en minutos mayor a cero.\", vbExclamation, \"Atencion\"\n        Exit Sub\n    End If\n    segTotal = m * 60\n    activo = True\n    TimerCuenta.Enabled = True\n    txtMinutos.Enabled = False\n    cmdIniciar.Enabled = False\n    MsgBox \"Temporizador activado. Cuenta regresiva iniciada.\", vbInformation, \"Iniciado\"\nEnd Sub\n\nPrivate Sub cmdCancelar_Click()\n    activo = False\n    TimerCuenta.Enabled = False\n    txtMinutos.Enabled = True\n    cmdIniciar.Enabled = True\n    txtMinutos_Change\n    MsgBox \"Temporizador cancelado con exito.\", vbInformation, \"Cancelado\"\nEnd Sub\n\nPrivate Sub TimerCuenta_Timer()\n    If segTotal > 0 Then\n        segTotal = segTotal - 1\n        MostrarTiempo segTotal\n    Else\n        TimerCuenta.Enabled = False\n        activo = False\n        txtMinutos.Enabled = True\n        cmdIniciar.Enabled = True\n        EjecutarAccion\n    End If\nEnd Sub\n\nPrivate Sub EjecutarAccion()\n    Beep\n    If optAlarma.Value Then\n        MsgBox \"TIEMPO FINALIZADO. Alarma sonora completada.\", vbInformation, \"Alarma\"\n    ElseIf optCerrarSesion.Value Then\n        MsgBox \"TIEMPO FINALIZADO. Cerrando sesion de usuario simulada.\", vbInformation, \"Cerrar Sesion\"\n    ElseIf optReiniciar.Value Then\n        MsgBox \"TIEMPO FINALIZADO. Reiniciando equipo de forma programada.\", vbInformation, \"Reiniciar\"\n    Else\n        MsgBox \"TIEMPO FINALIZADO. Apagado de equipo simulado con exito.\", vbCritical, \"Apagado\"\n    End If\nEnd Sub"
        }
